use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Universe domain model
///
/// A Universe is a project container for creative work, holding all the context,
/// elements, and stories that belong to a particular creative world.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct Universe {
    // Core Identity
    pub id: String,
    pub name: String,
    pub description: String,
    pub created_at: String, // ISO 8601 timestamp
    pub updated_at: String, // ISO 8601 timestamp

    // Creative Context
    #[serde(skip_serializing_if = "Option::is_none")]
    pub genre: Option<Genre>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tone: Option<Tone>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub worldbuilding_notes: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub themes: Option<Vec<String>>,

    // Organization & Customization
    pub status: UniverseStatus,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub icon: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tags: Option<Vec<String>>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "lowercase")]
pub enum UniverseStatus {
    Active,
    Archived,
    Template,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "kebab-case")]
pub enum Genre {
    Fantasy,
    SciFi,
    Contemporary,
    Horror,
    Mystery,
    Romance,
    Thriller,
    Historical,
    Other,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "lowercase")]
pub enum Tone {
    Dark,
    Comedic,
    Serious,
    Lighthearted,
    Dramatic,
    Satirical,
    Other,
}

/// Input for creating a new Universe
#[derive(Debug, Clone, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct CreateUniverseInput {
    pub name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub genre: Option<Genre>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tone: Option<Tone>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub worldbuilding_notes: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub themes: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub icon: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tags: Option<Vec<String>>,
}

/// Input for updating an existing Universe
#[derive(Debug, Clone, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct UpdateUniverseInput {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub genre: Option<Genre>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tone: Option<Tone>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub worldbuilding_notes: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub themes: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub status: Option<UniverseStatus>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub icon: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tags: Option<Vec<String>>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_universe_serialization_round_trip() {
        let universe = Universe {
            id: "test-id".to_string(),
            name: "Test Universe".to_string(),
            description: "A test universe".to_string(),
            created_at: "2024-01-01T00:00:00Z".to_string(),
            updated_at: "2024-01-01T00:00:00Z".to_string(),
            genre: Some(Genre::Fantasy),
            tone: Some(Tone::Dark),
            worldbuilding_notes: Some("Magic system notes".to_string()),
            themes: Some(vec!["adventure".to_string(), "friendship".to_string()]),
            status: UniverseStatus::Active,
            color: Some("#FF5733".to_string()),
            icon: Some("🌌".to_string()),
            tags: Some(vec!["epic".to_string(), "series".to_string()]),
        };

        let json = serde_json::to_string(&universe).unwrap();
        let deserialized: Universe = serde_json::from_str(&json).unwrap();

        assert_eq!(universe.id, deserialized.id);
        assert_eq!(universe.name, deserialized.name);
        assert_eq!(universe.genre, deserialized.genre);
    }

    #[test]
    fn test_universe_with_optional_fields_none() {
        let universe = Universe {
            id: "test-id".to_string(),
            name: "Minimal Universe".to_string(),
            description: "A minimal universe".to_string(),
            created_at: "2024-01-01T00:00:00Z".to_string(),
            updated_at: "2024-01-01T00:00:00Z".to_string(),
            genre: None,
            tone: None,
            worldbuilding_notes: None,
            themes: None,
            status: UniverseStatus::Active,
            color: None,
            icon: None,
            tags: None,
        };

        let json = serde_json::to_string(&universe).unwrap();
        let deserialized: Universe = serde_json::from_str(&json).unwrap();

        assert_eq!(universe.id, deserialized.id);
        assert!(deserialized.genre.is_none());
        assert!(deserialized.tags.is_none());
    }

    #[test]
    fn test_genre_serialization() {
        let genre = Genre::SciFi;
        let json = serde_json::to_string(&genre).unwrap();
        assert_eq!(json, "\"sci-fi\"");

        let deserialized: Genre = serde_json::from_str(&json).unwrap();
        assert!(matches!(deserialized, Genre::SciFi));
    }

    #[test]
    fn test_universe_status_serialization() {
        let status = UniverseStatus::Active;
        let json = serde_json::to_string(&status).unwrap();
        assert_eq!(json, "\"active\"");

        let deserialized: UniverseStatus = serde_json::from_str(&json).unwrap();
        assert!(matches!(deserialized, UniverseStatus::Active));
    }

    #[test]
    fn test_universe_json_uses_camel_case() {
        let universe = Universe {
            id: "test".to_string(),
            name: "Test".to_string(),
            description: "Test".to_string(),
            created_at: "2024-01-01T00:00:00Z".to_string(),
            updated_at: "2024-01-01T00:00:00Z".to_string(),
            genre: None,
            tone: None,
            worldbuilding_notes: Some("notes".to_string()),
            themes: None,
            status: UniverseStatus::Active,
            color: None,
            icon: None,
            tags: None,
        };

        let json = serde_json::to_string(&universe).unwrap();
        assert!(json.contains("createdAt"));
        assert!(json.contains("updatedAt"));
        assert!(json.contains("worldbuildingNotes"));
    }
}

use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Maximum allowed nesting depth for containers to prevent performance issues
/// and enforce reasonable hierarchy limits. A depth of 10 allows for complex
/// structures like: Universe → Series → Collection → Arc → Volume → Novel → Part → Chapter → Scene → Section
pub const MAX_NESTING_DEPTH: u32 = 10;

/// Container domain model
///
/// A Container represents an organizational entity within a Universe that can contain
/// either child containers or stories. Examples include novels, series, collections.
/// Containers support nesting: a "series" can contain "novels", and "novels" can contain
/// "chapters" (which are stories, not containers).
///
/// With Database-Only Versioning (DBV), containers no longer have Git repositories.
/// Versioning is handled at the story level through versions and snapshots.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct Container {
    // Core Identity
    pub id: String,
    pub universe_id: String,

    // Hierarchy
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parent_container_id: Option<String>,

    // Container Properties
    pub container_type: String,
    pub title: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    pub order: i32,

    // Timestamps
    pub created_at: String,
    pub updated_at: String,
}

/// Input for creating a new Container
#[derive(Debug, Clone, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct CreateContainerInput {
    pub universe_id: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parent_container_id: Option<String>,
    pub container_type: String,
    pub title: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub order: Option<i32>,
}

/// Input for updating an existing Container
#[derive(Debug, Clone, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct UpdateContainerInput {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub container_type: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub order: Option<i32>,
}

/// Response type containing child containers and stories
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct ContainerChildren {
    pub containers: Vec<Container>,
    pub stories: Vec<crate::models::StorySummary>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_container_serialization_round_trip() {
        let container = create_test_container();

        let json = serde_json::to_string(&container).unwrap();
        let deserialized: Container = serde_json::from_str(&json).unwrap();

        assert_eq!(container.id, deserialized.id);
        assert_eq!(container.title, deserialized.title);
        assert_eq!(container.container_type, deserialized.container_type);
        assert_eq!(
            container.parent_container_id,
            deserialized.parent_container_id
        );
    }

    #[test]
    fn test_container_json_uses_camel_case() {
        let container = Container {
            id: "test".to_string(),
            universe_id: "univ".to_string(),
            parent_container_id: Some("parent".to_string()),
            container_type: "novel".to_string(),
            title: "Test".to_string(),
            description: Some("Test description".to_string()),
            order: 1,
            created_at: "2024-01-01T00:00:00Z".to_string(),
            updated_at: "2024-01-01T00:00:00Z".to_string(),
        };

        let json = serde_json::to_string(&container).unwrap();
        assert!(json.contains("universeId"));
        assert!(json.contains("parentContainerId"));
        assert!(json.contains("containerType"));
        assert!(json.contains("createdAt"));
        assert!(json.contains("updatedAt"));
        // Verify git fields are NOT present (removed in DBV)
        assert!(!json.contains("gitRepoPath"));
        assert!(!json.contains("currentBranch"));
        assert!(!json.contains("stagedChanges"));
    }

    #[test]
    fn test_container_with_parent() {
        // A novel within a series
        let nested = Container {
            id: "novel-1".to_string(),
            universe_id: "universe-1".to_string(),
            parent_container_id: Some("series-1".to_string()),
            container_type: "novel".to_string(),
            title: "Book 1".to_string(),
            description: None,
            order: 1,
            created_at: "2024-01-01T00:00:00Z".to_string(),
            updated_at: "2024-01-01T00:00:00Z".to_string(),
        };

        let json = serde_json::to_string(&nested).unwrap();
        let deserialized: Container = serde_json::from_str(&json).unwrap();

        assert_eq!(
            deserialized.parent_container_id,
            Some("series-1".to_string())
        );
    }

    #[test]
    fn test_container_hierarchy() {
        // A series that contains novels
        let series = Container {
            id: "series-1".to_string(),
            universe_id: "universe-1".to_string(),
            parent_container_id: None,
            container_type: "series".to_string(),
            title: "The Trilogy".to_string(),
            description: Some("A three-part epic".to_string()),
            order: 1,
            created_at: "2024-01-01T00:00:00Z".to_string(),
            updated_at: "2024-01-01T00:00:00Z".to_string(),
        };

        let json = serde_json::to_string(&series).unwrap();
        let deserialized: Container = serde_json::from_str(&json).unwrap();

        assert_eq!(deserialized.container_type, "series");
        assert!(deserialized.parent_container_id.is_none());
    }

    #[test]
    fn test_container_optional_fields_skipped_when_none() {
        let container = Container {
            id: "container-1".to_string(),
            universe_id: "universe-1".to_string(),
            parent_container_id: None,
            container_type: "novel".to_string(),
            title: "Test".to_string(),
            description: None,
            order: 1,
            created_at: "2024-01-01T00:00:00Z".to_string(),
            updated_at: "2024-01-01T00:00:00Z".to_string(),
        };

        let json = serde_json::to_string(&container).unwrap();
        // Optional None fields should be skipped
        assert!(!json.contains("parentContainerId"));
        assert!(!json.contains("description"));
    }

    fn create_test_container() -> Container {
        Container {
            id: "container-1".to_string(),
            universe_id: "universe-1".to_string(),
            parent_container_id: Some("parent-1".to_string()),
            container_type: "novel".to_string(),
            title: "The Great Novel".to_string(),
            description: Some("An epic tale".to_string()),
            order: 1,
            created_at: "2024-01-01T00:00:00Z".to_string(),
            updated_at: "2024-01-01T00:00:00Z".to_string(),
        }
    }
}

use serde::{Deserialize, Serialize};
use ts_rs::TS;

use super::{StorySnapshot, StoryVersion};

/// Story domain model (internal, used by repository layer)
///
/// A Story is a written work within a Universe. It can be a novel, script, screenplay,
/// or any other type of creative writing. Stories support variations and database-based versioning.
///
/// Content is stored in the versioning system:
/// - Story → Version → Snapshot hierarchy
/// - active_version_id and active_snapshot_id point to the current working state
/// - active_version and active_snapshot are inline JOINed data for convenience
///
/// For API responses, use `StorySummary` (list endpoints) or `StoryDetail` (get endpoint).
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct Story {
    // Core Identity
    pub id: String,
    pub universe_id: String,
    pub title: String,
    pub description: String,
    pub created_at: String, // ISO 8601 timestamp
    pub updated_at: String, // ISO 8601 timestamp

    // Story Type & Status
    pub story_type: StoryType,
    pub status: StoryStatus,
    pub word_count: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target_word_count: Option<u32>,

    // Notes & Outline (not versioned)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub notes: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub outline: Option<String>,

    // Organization
    #[serde(skip_serializing_if = "Option::is_none")]
    pub order: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tags: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub favorite: Option<bool>,

    // Context & Relationships
    #[serde(skip_serializing_if = "Option::is_none")]
    pub related_element_ids: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub container_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub series_name: Option<String>,

    // Metadata
    pub last_edited_at: String, // ISO 8601 timestamp
    pub version: u32,

    // Variations
    pub variation_group_id: String,
    pub variation_type: VariationType,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parent_variation_id: Option<String>,

    // Database Versioning (DBV)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub active_version_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub active_snapshot_id: Option<String>,

    // Inline JOINed data for convenience (populated by queries)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub active_version: Option<StoryVersion>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub active_snapshot: Option<StorySnapshot>,
}

/// Lightweight Story representation for list endpoints.
///
/// Excludes hydrated version/snapshot data to keep list responses lean.
/// Used by `list_stories_by_universe`, `list_stories_by_container`, etc.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct StorySummary {
    // Core Identity
    pub id: String,
    pub universe_id: String,
    pub title: String,
    pub description: String,
    pub created_at: String,
    pub updated_at: String,

    // Story Type & Status
    pub story_type: StoryType,
    pub status: StoryStatus,
    pub word_count: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target_word_count: Option<u32>,

    // Organization
    #[serde(skip_serializing_if = "Option::is_none")]
    pub order: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tags: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub favorite: Option<bool>,

    // Context & Relationships
    #[serde(skip_serializing_if = "Option::is_none")]
    pub container_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub series_name: Option<String>,

    // Metadata
    pub last_edited_at: String,
    pub version: u32,

    // Variations
    pub variation_group_id: String,
    pub variation_type: VariationType,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parent_variation_id: Option<String>,
}

impl From<Story> for StorySummary {
    fn from(story: Story) -> Self {
        StorySummary {
            id: story.id,
            universe_id: story.universe_id,
            title: story.title,
            description: story.description,
            created_at: story.created_at,
            updated_at: story.updated_at,
            story_type: story.story_type,
            status: story.status,
            word_count: story.word_count,
            target_word_count: story.target_word_count,
            order: story.order,
            tags: story.tags,
            color: story.color,
            favorite: story.favorite,
            container_id: story.container_id,
            series_name: story.series_name,
            last_edited_at: story.last_edited_at,
            version: story.version,
            variation_group_id: story.variation_group_id,
            variation_type: story.variation_type,
            parent_variation_id: story.parent_variation_id,
        }
    }
}

/// Rich Story representation for single-story endpoints (get_story).
///
/// Includes the active version and snapshot data inline, guaranteeing
/// they are present (non-optional) for a properly initialized story.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../src/types/")]
#[serde(rename_all = "camelCase")]
pub struct StoryDetail {
    // Core Identity
    pub id: String,
    pub universe_id: String,
    pub title: String,
    pub description: String,
    pub created_at: String,
    pub updated_at: String,

    // Story Type & Status
    pub story_type: StoryType,
    pub status: StoryStatus,
    pub word_count: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target_word_count: Option<u32>,

    // Notes & Outline (not versioned)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub notes: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub outline: Option<String>,

    // Organization
    #[serde(skip_serializing_if = "Option::is_none")]
    pub order: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tags: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub color: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub favorite: Option<bool>,

    // Context & Relationships
    #[serde(skip_serializing_if = "Option::is_none")]
    pub related_element_ids: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub container_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub series_name: Option<String>,

    // Metadata
    pub last_edited_at: String,
    pub version: u32,

    // Variations
    pub variation_group_id: String,
    pub variation_type: VariationType,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parent_variation_id: Option<String>,

    // Database Versioning (DBV) - guaranteed present for initialized stories
    pub active_version_id: String,
    pub active_snapshot_id: String,
    pub active_version: StoryVersion,
    pub active_snapshot: StorySnapshot,
}

impl StoryDetail {
    /// Build a StoryDetail from a Story with its hydrated version and snapshot.
    /// Returns an error if active version or snapshot are missing.
    pub fn from_story(story: Story) -> Result<Self, String> {
        let active_version_id = story
            .active_version_id
            .ok_or_else(|| format!("Story {} has no active_version_id", story.id))?;
        let active_snapshot_id = story
            .active_snapshot_id
            .ok_or_else(|| format!("Story {} has no active_snapshot_id", story.id))?;
        let active_version = story
            .active_version
            .ok_or_else(|| format!("Story {} has no active_version populated", story.id))?;
        let active_snapshot = story
            .active_snapshot
            .ok_or_else(|| format!("Story {} has no active_snapshot populated", story.id))?;

        Ok(StoryDetail {
            id: story.id,
            universe_id: story.universe_id,
            title: story.title,
            description: story.description,
            created_at: story.created_at,
            updated_at: story.updated_at,
            story_type: story.story_type,
            status: story.status,
            word_count: story.word_count,
            target_word_count: story.target_word_count,
            notes: story.notes,
            outline: story.outline,
            order: story.order,
            tags: story.tags,
            color: story.color,
